-- ASCII-safe re-seed (PostgreSQL U& unicode escapes). Safe to paste in SQL Editor.
-- Clears exercises then upserts 38 from data/exercises.ts. No raw Hebrew bytes.
-- Verify: select id, name_he from public.exercises where id = 'ex_pushup';

delete from public.exercises;

on conflict (id) do update set
  name_he = excluded.name_he,
  name_en = excluded.name_en,
  category = excluded.category,
  level = excluded.level,
  aliases = excluded.aliases,
  cue_he = excluded.cue_he;

-- expected rows: 38
